CREATE TYPE "Role" AS ENUM ('ADMIN','SALES','WAREHOUSE','FINANCE','CUSTOMER');
CREATE TYPE "OrderStatus" AS ENUM ('RECEIVED','CONFIRMED','PREPARING','SHIPPED','DELIVERED','CANCELLED');
CREATE TABLE "User" (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,"passwordHash" TEXT NOT NULL,role "Role" NOT NULL DEFAULT 'CUSTOMER',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Session" (id TEXT PRIMARY KEY,"tokenHash" TEXT NOT NULL UNIQUE,"userId" TEXT NOT NULL REFERENCES "User"(id),"expiresAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt");
CREATE TABLE "Brand" (id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE "Product" (id TEXT PRIMARY KEY,sku TEXT NOT NULL UNIQUE,name TEXT NOT NULL,"brandId" TEXT NOT NULL REFERENCES "Brand"(id),collection TEXT,size TEXT,color TEXT,surface TEXT,"boxArea" DECIMAL(12,4) NOT NULL CHECK ("boxArea">0),price DECIMAL(14,2) NOT NULL CHECK(price>=0),"vatRate" DECIMAL(5,2) NOT NULL CHECK("vatRate" BETWEEN 0 AND 100),active BOOLEAN NOT NULL DEFAULT true,demo BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Warehouse" (id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE "InventoryLot" (id TEXT PRIMARY KEY,"productId" TEXT NOT NULL REFERENCES "Product"(id),"warehouseId" TEXT NOT NULL REFERENCES "Warehouse"(id),batch TEXT NOT NULL,tone TEXT,caliber TEXT,physical INTEGER NOT NULL,reserved INTEGER NOT NULL DEFAULT 0,CONSTRAINT stock_valid CHECK (physical>=0 AND reserved>=0 AND reserved<=physical),UNIQUE("productId","warehouseId",batch));
CREATE INDEX "InventoryLot_productId_idx" ON "InventoryLot"("productId");
CREATE TABLE "Order" (id TEXT PRIMARY KEY,number TEXT NOT NULL UNIQUE,"userId" TEXT NOT NULL REFERENCES "User"(id),"idempotencyKey" TEXT NOT NULL,status "OrderStatus" NOT NULL DEFAULT 'RECEIVED',subtotal DECIMAL(14,2) NOT NULL,tax DECIMAL(14,2) NOT NULL,total DECIMAL(14,2) NOT NULL,"deliveryAddress" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("userId","idempotencyKey"));
CREATE INDEX "Order_createdAt_idx" ON "Order"("createdAt");
CREATE TABLE "OrderItem" (id TEXT PRIMARY KEY,"orderId" TEXT NOT NULL REFERENCES "Order"(id),"productId" TEXT NOT NULL REFERENCES "Product"(id),sku TEXT NOT NULL,name TEXT NOT NULL,boxes INTEGER NOT NULL CHECK(boxes>0),area DECIMAL(12,4) NOT NULL,"unitPrice" DECIMAL(14,2) NOT NULL,"vatRate" DECIMAL(5,2) NOT NULL,subtotal DECIMAL(14,2) NOT NULL,tax DECIMAL(14,2) NOT NULL,total DECIMAL(14,2) NOT NULL,"lotId" TEXT NOT NULL REFERENCES "InventoryLot"(id));
CREATE TABLE "OrderStatusHistory" (id TEXT PRIMARY KEY,"orderId" TEXT NOT NULL REFERENCES "Order"(id),status "OrderStatus" NOT NULL,"actorId" TEXT NOT NULL REFERENCES "User"(id),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog" (id TEXT PRIMARY KEY,"actorId" TEXT NOT NULL REFERENCES "User"(id),action TEXT NOT NULL,"entityId" TEXT NOT NULL,data JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "AuditLog_entityId_createdAt_idx" ON "AuditLog"("entityId","createdAt");
